{{ config(
            materialized='table',
                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; CREATE OR REPLACE TABLE snitch_db.maplemonk.logic_in_out_summary AS WITH offline_store_mapping AS ( SELECT store_name, region, cluster, party FROM SNITCH_DB.MAPLEMONK.OFFLINE_STORE_DETAILED_MAPPING ), warehouse_sales AS ( SELECT \'UC-SALE\' as CAT1, \'UC\' AS SOURCE, CASE WHEN lower(marketplace_mapped) like \'%store%\' THEN \'STORE-OUTWARD\' ELSE \'SALES\' END AS SUBTYPE, \'OUTWARD\' AS TYPE, \'WH-Sale\' AS ORIGIN, dispatched_timestamp::DATE AS DATE, CASE WHEN warehouse_name = \'SAPL_EMIZA\' THEN \'SNITCH - WH - EMIZA\' WHEN warehouse_name = \'SAPL-WH2\' THEN \'SNITCH - WH - YELHANKA 2\' WHEN warehouse_name = \'SAPL-WH1\' THEN \'SNITCH - WH - YELHANKA\' ELSE \'NA\' END AS FROM_PARTY, marketplace_mapped AS TO_PARTY, COUNT(saleorderitemcode) AS QTY FROM snitch_db.maplemonk.warehouse_sla_performance WHERE dispatched_timestamp IS NOT NULL AND dispatched_timestamp >= \'2025-01-01\' and warehouse_name not like \'%EBO%\' GROUP BY 1,2,3,4,5,6,7,8 ), warehouse_inward AS ( SELECT \'UC-IN\' as CAT1, \'UC\' AS SOURCE, CASE WHEN LOWER(final_type) LIKE \'%return%\' THEN \'RETURNS\' WHEN LOWER(final_type) LIKE \'%inward%\' THEN \'NEW\' ELSE \'NA\' END AS SUBTYPE, \'INWARD\' AS TYPE, \'WH-Inward\' AS ORIGIN, putaway_created::DATE AS DATE, final_type AS FROM_PARTY, CASE WHEN \"Warehouse Name\" = \'SAPL_EMIZA\' THEN \'SNITCH - WH - EMIZA\' WHEN \"Warehouse Name\" = \'SAPL-WH2\' THEN \'SNITCH - WH - YELHANKA 2\' WHEN \"Warehouse Name\" = \'SAPL-WH1\' THEN \'SNITCH - WH - YELHANKA\' ELSE \'NA\' END AS TO_PARTY, SUM(total_quantity) AS QTY FROM snitch_db.maplemonk.putaway_tracking WHERE LOWER(final_type) LIKE \'%inward%\' or LOWER(final_type) LIKE \'%return%\' AND putaway_created >= \'2025-01-01\' GROUP BY 1,2,3,4,5,6,7,8 ), logic_sti AS ( SELECT \'LOGIC-STI\' as CAT1, \'LOGIC\' AS SOURCE, CASE WHEN to_party like \'%YEL%\' or to_party like \'%EMIZA%\' THEN \'RETURNS\' ELSE \'STORE-INWARD\' END AS SUBTYPE, \'INWARD\' as TYPE, ORIGIN, bill_date AS DATE, from_party, to_party, SUM(item_quantity) AS QTY FROM snitch_db.maplemonk.logic_final_sti GROUP BY 1,2,3,4,5,6,7,8 ), store_sales AS ( SELECT \'LOGIC-SALE\' as CAT1, \'LOGIC\' AS SOURCE, \'SALES\' AS SUBTYPE, \'OUTWARD\' as TYPE, CASE WHEN marketplace_mapped LIKE \'%SNITCH - WH%\' THEN \'WH-Sale\' WHEN marketplace_mapped LIKE \'%COCO%\' OR marketplace_mapped LIKE \'%FOCO%\' OR marketplace_mapped LIKE \'%COFO%\' OR marketplace_mapped LIKE \'%JAYAN%\' OR marketplace_mapped LIKE \'%BRIG%\' OR marketplace_mapped LIKE \'%SNITCH%\' THEN \'STORE-Sale\' ELSE \'NA\' END AS ORIGIN, order_date AS DATE, marketplace_mapped AS FROM_PARTY, \'sale\' AS TO_PARTY, COUNT(marketplace_mapped) AS QTY FROM snitch_db.maplemonk.store_fact_items_offline GROUP BY 1,2,3,4,5,6,7,8 ), store_returns AS ( SELECT \'LOGIC-RETURNS\' as CAT1, \'LOGIC\' AS SOURCE, \'RETURNS\' AS SUBTYPE, \'INWARD\' AS TYPE, CASE WHEN ORDER_ID LIKE \'%WER%\' THEN \'WH-B2C-Return\' WHEN marketplace_mapped LIKE \'%COCO%\' OR marketplace_mapped LIKE \'%FOCO%\' OR marketplace_mapped LIKE \'%COFO%\' OR marketplace_mapped LIKE \'%JAYAN%\' OR marketplace_mapped LIKE \'%BRIG%\' THEN \'STORE-Return\' ELSE \'OTHERS\' END AS ORIGIN, order_date AS DATE, \'return\' AS FROM_PARTY, marketplace_mapped AS TO_PARTY, COUNT(marketplace_mapped) AS QTY FROM snitch_db.maplemonk.store_returns_fact_items GROUP BY 1,2,3,4,5,6,7,8 ), logic_purchase_voucher AS ( SELECT \'LOGIC-PV\' as CAT1, \'LOGIC\' AS SOURCE, CASE WHEN to_party like \'%CO%\' or to_party like \'%FO%\' THEN \'STORE-INWARD\' ELSE \'NEW\' END AS SUBTYPE, \'INWARD\' AS TYPE, ORIGIN, bill_date AS DATE, from_party, to_party, SUM(item_quantity) AS QTY FROM snitch_db.maplemonk.logic_purchase_voucher GROUP BY 1,2,3,4,5,6,7,8 ), logic_final_sto AS ( SELECT \'LOGIC-STO\' as CAT1, \'LOGIC\' AS SOURCE, \'STORE-OUTWARD\' as SUBTYPE, \'OUTWARD\' as TYPE, ORIGIN, COALESCE(TRY_TO_DATE(bill_date, \'YYYY-MM-DD\'), TRY_TO_DATE(bill_date, \'DD/MM/YYYY\')) AS DATE, from_party, to_party, SUM(item_quantity) AS QTY FROM snitch_db.maplemonk.logic_final_sto GROUP BY 1,2,3,4,5,6,7,8 ), logic_purchase_return as ( select \'LOGIC-PR\' as CAT1, \'LOGIC\' AS SOURCE, \'STORE-OUTWARD\' as SUBTYPE, \'OUTWARD\' as TYPE, ORIGIN, COALESCE(TRY_TO_DATE(bill_date, \'YYYY-MM-DD\'), TRY_TO_DATE(bill_date, \'DD/MM/YYYY\')) AS DATE, from_party, to_party, SUM(item_qty) AS QTY from SNITCH_DB.MAPLEMONK.PURCHASE_RETURN GROUP BY 1,2,3,4,5,6,7,8 ) SELECT * FROM ( SELECT a.*,b.* FROM warehouse_sales a LEFT JOIN offline_store_mapping b on a.from_party = b.store_name UNION ALL SELECT a.*,b.* FROM warehouse_inward a LEFT JOIN offline_store_mapping b on a.to_party = b.store_name UNION ALL SELECT a.*,b.* FROM logic_sti a LEFT JOIN offline_store_mapping b on a.to_party = b.store_name UNION ALL SELECT a.*,b.* FROM store_sales a LEFT JOIN offline_store_mapping b on a.from_party = b.store_name UNION ALL SELECT a.*,b.* FROM store_returns a LEFT JOIN offline_store_mapping b on a.to_party = b.store_name UNION ALL SELECT a.*,b.* FROM logic_purchase_voucher a LEFT JOIN offline_store_mapping b on a.to_party = b.store_name UNION ALL SELECT a.*,b.* FROM logic_final_sto a LEFT JOIN offline_store_mapping b on a.from_party = b.store_name UNION ALL SELECT a.*,b.* FROM logic_purchase_return a LEFT JOIN offline_store_mapping b on a.from_party = b.store_name ) AS final_data ORDER BY DATE DESC;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            